import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";

function WatchPage() {
  const { id } = useParams();
  const [video, setVideo] = useState(null);

  // Lấy video theo ID từ localStorage
  useEffect(() => {
    const allVideos = JSON.parse(localStorage.getItem("videos") || "[]");
    const current = allVideos.find((v) => v.id === id);
    setVideo(current);
  }, [id]);

  // Ghi lại vào lịch sử xem
  useEffect(() => {
    if (!video) return;

    const watched = {
      id: video.id,
      title: video.title,
      desc: video.desc,
      url: video.url,
      watchedAt: Date.now(),
    };

    const history = JSON.parse(localStorage.getItem("history") || "[]");

    // Xoá nếu đã có để không trùng
    const filtered = history.filter((v) => v.id !== watched.id);

    // Ghi mới lên đầu
    const updated = [watched, ...filtered];

    localStorage.setItem("history", JSON.stringify(updated));
  }, [video]);

  if (!video) {
    return (
      <div className="p-10 text-gray-600 text-lg">
        ❗ Video không tồn tại hoặc đã bị xoá.
      </div>
    );
  }

  return (
    <div className="min-h-screen p-6 space-y-4">
      <video
        src={video.url}
        controls
        className="w-full max-h-[70vh] rounded shadow"
      />
      <h1 className="text-2xl font-bold text-gray-800">{video.title}</h1>
      <p className="text-gray-600">{video.desc}</p>
    </div>
  );
}

export default WatchPage;
